        # If we need resources, move toward resource-rich area if available
        rx = granary.get("resource_x", None)
        ry = granary.get("resource_y", None)
        if rx is not None and ry is not None:
            # Move one step toward resource coordinate
            if rx > obs.get("pos_x", 0):
                x = 1
            elif rx < obs.get("pos_x", 0):
                x = -1
            if ry > obs.get("pos_y", 0):
                y = 1
            elif ry < obs.get("pos_y", 0):
