            return [x, y]

    # If in pursuit_evasion mode, chase closer to evader if known
    evader = obs.get("evader", {})
    if isinstance(evader, dict):
        ex = evader.get("x", None)
        ey = evader.get("y", None)
        if ex is not None and ey is not None:
            px = obs.get("pos_x", 0)
            py = obs.get("pos_y", 0)
            if ex > px:
                x = 1
            elif ex < px:
                x = -1
            if ey > py:
                y = 1
            elif ey < py:
                y = -1
            return [x, y]

    # If territory_control, try to move to center or guarding positions defensively
    center = obs.get("center", {})
    if isinstance(center, dict):
        cx = center.get("x", None)
        cy = center.get("y", None)
        if cx is not None and cy is not None:
            px = obs.get("pos_x", 0)
            py = obs.get("pos_y", 0)
            if cx > px:
                x = 1
            elif cx < px:
                x = -1
            if cy > py:
                y = 1
            elif cy < py:
                y = -1
            return [x, y]

    # Fallback: move randomly-safe by steering to stay within bounds [-1,1]
    # Use observation position if available to keep deterministic behavior
    px = obs.get("pos_x", 0)
    py = obs.get("pos_y", 0)

    # If near edges (0,0)-(max), try to offset slightly away from origin
    if px == 0:
        x = 1
    if py == 0:
        y = 1

    return [x, y]

